160	        public async Task<ActionResult<RatingSubmissionResponseDto>> SubmitRating(
161	            string productId,
162	            [FromBody] SubmitRatingRequest request,
163	            CancellationToken ct = default)
164	        {
165	            var aggregate = await ratingService.SubmitRatingAsync(productId, request.AuthorName, request.Score, ct);
166	            if (aggregate is null)
167	            {
168	                return NotFound();
169	            }
170	
171	            return Ok(new RatingSubmissionResponseDto
172	            {
173	                AverageRating = aggregate.AverageRating,
174	                RatingCount = aggregate.RatingCount
175	            });
176	        }
177	    }
178	    ```
